-- Generated by scripts/prepare-world-nationalities.cjs; UTF-8.
-- Legacy names recovered from GeziraLastMemberShip with exact original IDs/codes.
-- Additional entries: ISO3166-1 countries/territories; Arabic Unicode CLDR names via Node Intl.
-- Sources: https://www.iso.org/iso-3166-country-codes.html
-- https://github.com/unicode-org/cldr-json/tree/main/cldr-json/cldr-localenames-full/main/ar
-- Does not update public.members, IDs or existing codes. Refuses conflicting names.
BEGIN;
SET LOCAL lock_timeout = '10s';
LOCK TABLE public.lookup_nationality IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE nationality_world_seed(code INTEGER PRIMARY KEY, name TEXT NOT NULL, legacy BOOLEAN NOT NULL) ON COMMIT DROP;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM public.lookup_nationality n JOIN nationality_world_seed s USING(code)
    WHERE n.name IS DISTINCT FROM s.name AND NOT (s.legacy AND lower(btrim(n.name)) = 'xxx')) THEN
    RAISE EXCEPTION 'Nationality code/name conflict; review mapping before applying';
  END IF;
END $$;
UPDATE public.lookup_nationality n SET name = s.name FROM nationality_world_seed s
WHERE n.code = s.code AND s.legacy AND lower(btrim(n.name)) = 'xxx';
SELECT (SELECT COALESCE(MAX(id),0) FROM public.lookup_nationality) + ROW_NUMBER() OVER (ORDER BY s.code), s.code,s.name
FROM nationality_world_seed s WHERE NOT EXISTS(SELECT 1 FROM public.lookup_nationality n WHERE n.code=s.code);
DO $$ DECLARE sequence_name TEXT; previous_value BIGINT; maximum_id BIGINT; BEGIN
  SELECT pg_get_serial_sequence('public.lookup_nationality','id'), MAX(id) INTO sequence_name, maximum_id FROM public.lookup_nationality;
  IF sequence_name IS NOT NULL THEN
    EXECUTE format('SELECT last_value FROM %s', sequence_name) INTO previous_value;
    PERFORM setval(sequence_name::regclass, GREATEST(maximum_id,previous_value),true);
  END IF;
END $$;
COMMIT;
